import math
import numpy as np


def _paired_vectors(ratios, advantages):
    rho = np.asarray(ratios, dtype=float)
    adv = np.asarray(advantages, dtype=float)
    if rho.ndim != 1 or adv.shape != rho.shape or rho.size == 0:
        raise ValueError("ratios and advantages must be equal non-empty vectors")
    if not np.all(np.isfinite(rho)) or not np.all(np.isfinite(adv)):
        raise ValueError("ratios and advantages must be finite")
    if np.any(rho <= 0):
        raise ValueError("ratios must be strictly positive")
    return rho, adv


def clipped_terms(ratios, advantages, eps_low=0.2, eps_high=None):
    rho, adv = _paired_vectors(ratios, advantages)
    if eps_high is None:
        eps_high = eps_low
    if eps_low < 0 or eps_high < 0 or not math.isfinite(eps_low) or not math.isfinite(eps_high):
        raise ValueError("clip widths must be finite and non-negative")
    clipped = np.clip(rho, 1.0 - eps_low, 1.0 + eps_high)
    return np.minimum(rho * adv, clipped * adv)


def clip_activity(ratios, advantages, eps_low=0.2, eps_high=None):
    rho, adv = _paired_vectors(ratios, advantages)
    if eps_high is None:
        eps_high = eps_low
    if eps_low < 0 or eps_high < 0:
        raise ValueError("clip widths must be non-negative")
    return ((adv > 0) & (rho > 1.0 + eps_high)) | ((adv < 0) & (rho < 1.0 - eps_low))
```

```python
ratios = np.array([1.50, 1.25, 0.70, 1.10])
advs = np.array([1.00, 1.00, -1.00, 1.00])
sym = clipped_terms(ratios, advs, eps_low=0.2)
asym = clipped_terms(ratios, advs, eps_low=0.2, eps_high=0.28)
assert np.allclose(sym, [1.2, 1.2, -0.8, 1.1])
assert np.allclose(asym, [1.28, 1.25, -0.8, 1.1])
assert np.array_equal(
    clip_activity(ratios, advs, eps_low=0.2, eps_high=0.28),
    [True, False, True, False],
)
```

Clip-Higher releases the second positive term but does not change the lower bound for a negative advantage. The mask marks positions where the minimum selected the constant clipped branch, so the local derivative with respect to the ratio is zero.

```python
import math
import numpy as np


def _rewards_and_lengths(rewards, lengths):
    r = np.asarray(rewards, dtype=float)
    lens = np.asarray(lengths, dtype=int)
    if r.ndim != 1 or r.size == 0 or not np.all(np.isfinite(r)):
        raise ValueError("rewards must be a non-empty finite vector")
    if lens.ndim != 1 or lens.shape != r.shape or np.any(lens <= 0):
        raise ValueError("lengths must be positive and match rewards")
    return r, lens


def _advantages(rewards, *, scale, eps=1e-8):
    centered = rewards - rewards.mean()
    if not scale:
        return centered
    if eps < 0 or not math.isfinite(eps):
        raise ValueError("eps must be finite and non-negative")
    std = float(rewards.std(ddof=0))
    return np.zeros_like(rewards) if std == 0.0 else centered / (std + eps)


def original_grpo_token_weights(rewards, lengths, *, eps=1e-8):
    r, lens = _rewards_and_lengths(rewards, lengths)
    adv = _advantages(r, scale=True, eps=eps)
    group_size = r.size
    return [
        np.full(int(length), a / (group_size * length), dtype=float)
        for a, length in zip(adv, lens)
    ]


def dr_grpo_token_weights(rewards, lengths, *, fixed_length):
    r, lens = _rewards_and_lengths(rewards, lengths)
    if fixed_length <= 0:
        raise ValueError("fixed_length must be positive")
    adv = _advantages(r, scale=False)
    group_size = r.size
    return [
        np.full(int(length), a / (group_size * fixed_length), dtype=float)
        for a, length in zip(adv, lens)
    ]


def dapo_token_weights(rewards, lengths, *, scale_rewards=True):
    r, lens = _rewards_and_lengths(rewards, lengths)
    adv = _advantages(r, scale=scale_rewards)
    total_active_tokens = int(lens.sum())
    return [
        np.full(int(length), a / total_active_tokens, dtype=float)
        for a, length in zip(adv, lens)
    ]


def response_contributions(token_weights):
    if not token_weights:
        raise ValueError("token_weights must be non-empty")
    return np.asarray([np.asarray(w, dtype=float).sum() for w in token_weights])
```

```python
rewards, lengths = [1.0, 0.0], [10, 1000]
assert np.allclose(
    response_contributions(original_grpo_token_weights(rewards, lengths)),
    [0.5, -0.5],
)
assert np.allclose(
    response_contributions(dr_grpo_token_weights(rewards, lengths, fixed_length=1000)),
    [0.0025, -0.25],
)
assert np.allclose(
    response_contributions(dapo_token_weights(rewards, lengths)),
    [10/1010, -1000/1010],
    atol=1e-8,
)
```

Original GRPO divides each response by its own length and therefore produces equal-magnitude response totals. In the shown Dr. GRPO and DAPO reductions, a token coefficient is not divided by that response’s length, so the total contribution becomes proportional to the number of active tokens. Their absolute scales differ because the global denominators and reward normalization differ.
